client.on('interactionCreate', async (interaction) => {
  if (!interaction.isCommand()) return;

  const { commandName } = interaction;

  // Handle the /ban command
  if (commandName === 'ban') {
    try {
      const member = interaction.options.getMember('member');
      const reason = interaction.options.getString('reason', true);

      // Check if the user has permission to ban
      if (!interaction.member.permissions.has('BanMembers')) {
        return interaction.reply({
          content: '❌ You do not have permission to ban users.',
          ephemeral: true,
        });
      }

      // Check if the member is the bot or self
      if (!member) {
        return interaction.reply({
          content: '❌ Please mention a valid user to ban.',
          ephemeral: true,
        });
      }

      // Check if the member is the bot or the user themselves
      if (member.id === interaction.client.user.id) {
        return interaction.reply({
          content: '❌ Cannot ban the bot itself.',
          ephemeral: true,
        });
      }

      // Ban the member
      await member.ban({
        reason: reason,
      });

      return interaction.reply({
        content: `✅ Successfully banned ${member.user.tag} for: ${reason}`,
      });
    } catch (error) {
      console.error('Error in /ban command:', error);
      return interaction.reply({
        content: '❌ An error occurred while banning the user.',
        ephemeral: true,
      });
    }
  }
});

// Login the bot
client.login(token);
