function findAndPrintPrime(numbers) {
    // Helper function to check if a number is prime
    function isPrime(n) {
        // Numbers less than or equal to 1 are not prime
        if (n <= 1) return false;
        if (n === 2) return true;
        if (n % 2 === 0) return false;

        // Check odd divisors up to sqrt(n)
        for (let i = 3; i <= Math.sqrt(n); i += 2) {
            if (n % i === 0) return false;
        }
        return true;
    }

    // Iterate through the array and check each number
    for (let num of numbers) {
        if (isPrime(num)) {
            console.log(num);
            return; // Once a prime is found, exit the function
        }
    }

    // If no prime is found, do nothing (no output)
    console.log("No prime number found.");
}

// Example usage:
findAndPrintPrime([4, 6, 7, 8, 10]);
// Output: 7

findAndPrintPrime([4, 6, 8, 9, 10]);
// Output: No prime number found.
```

